<script setup lang="ts">
import CircleAction from '@/components/ui/CircleAction.vue'
import {computed,ref} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import uniIcons from '@dcloudio/uni-ui/lib/uni-icons/uni-icons.vue'
import {api,selectedExamId,refreshRights,showApiError} from '@/services/api'
import {useAppStore} from '@/store/app'
import {refreshOrders} from '@/utils/orders'
import {payConfiguredOrder} from '@/utils/product-payment'
import {backOrFallback,openPage} from '@/utils/navigation'
const {requireLogin}=useAppStore()
const items=ref<any[]>([]),loading=ref(true),error=ref(''),selected=ref<any>(),filter=ref(''),paying=ref(false),requestedId=ref('')
const shown=computed(()=>items.value.filter(p=>!filter.value||p.type===filter.value))
const money=(c:number)=>(c/100).toFixed(2),date=(s:string)=>new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})
let revision=0
async function load(){const v=++revision,exam=selectedExamId();loading.value=true;error.value='';try{const list=await api<any[]>('/products?examId='+encodeURIComponent(exam));if(v===revision&&exam===selectedExamId()){items.value=list;selected.value=selected.value?list.find(p=>p.id===selected.value.id):list.find(p=>p.id===requestedId.value)}}catch(e:any){if(v===revision)error.value=e.message}finally{if(v===revision)loading.value=false}}
onLoad((query:any)=>{filter.value=query?.type==='trial'?'trial':'';requestedId.value=query?.id||''});onShow(load)
async function buy(){const p=selected.value;if(!p||paying.value||!requireLogin('/pages/products/index?id='+p.id))return;paying.value=true;try{const created=await api('/orders','POST',{productId:p.id});if(created.existing){await refreshOrders();uni.navigateTo({url:'/pages/profile-center/index?mode=orders'});return}const paid=await payConfiguredOrder(created.order.id);await refreshOrders();if(paid){await refreshRights();uni.showToast({title:'权益已生效，测试未扣款',icon:'none'})}else uni.showToast({title:'订单已保留，可在我的订单继续支付',icon:'none'})}catch(e){showApiError(e);void load()}finally{paying.value=false}}
function back(){backOrFallback('/pages/index/index')}
</script>
<template><view class="shop-page safe-top"><view class="shop-nav"><CircleAction @tap="back"/><text>{{selected?'商品详情':'会员套餐'}}</text><view/></view>
 <view v-if="loading" class="shop-message">正在加载商品…</view><view v-else-if="error" class="shop-message"><text>{{error}}</text><button @tap="load">重新加载</button></view>
 <template v-else-if="selected"><view class="shop-detail"><image v-if="selected.coverUrl" class="detail-cover" :src="selected.coverUrl" mode="aspectFit"/><view class="detail-card"><text class="shop-badge">{{selected.type==='trial'?'限时体验':'考期权益'}} · {{selected.level.toUpperCase()}}</text><text class="detail-title">{{selected.title}}</text><text class="detail-intro">{{selected.intro}}</text><view class="shop-price">¥<text>{{money(selected.priceCents)}}</text><text v-if="selected.originalPriceCents" class="shop-original">¥{{money(selected.originalPriceCents)}}</text></view><text class="shop-period">{{selected.examName}} · {{selected.year}} 年考期</text><text class="shop-period">{{selected.type==='trial'?`支付后体验 ${selected.trialHours} 小时，最晚至考期结束`:'支付成功后生效，有效至本考期结束'}}</text><text class="shop-period">考期结束：{{date(selected.endsAt)}}</text></view><view v-if="selected.html" class="detail-card"><text class="shop-section-title">商品介绍</text><rich-text class="shop-rich" :nodes="selected.html"/></view><text class="purchase-note">{{selected.type==='trial'?'每个账号终身只能体验一次，购买过正式权益后不能再体验。实际可购买时长将在支付前核对。':'同一考试考期内只可购买一次正式权益。到期恢复普通会员。'}}</text></view><view class="shop-footer"><view><text>实付金额</text><strong>¥{{money(selected.priceCents)}}</strong></view><button :disabled="paying" @tap="buy">{{paying?'正在处理…':'立即购买'}}</button></view></template>
 <template v-else><view class="shop-heading"><text>为这个考期，选一份支持</text><text>权益随所选考试生效，价格与内容以商品为准。</text></view><view class="shop-tabs"><button :class="{active:!filter}" @tap="filter=''">全部</button><button :class="{active:filter==='entitlement'}" @tap="filter='entitlement'">权益套餐</button><button :class="{active:filter==='trial'}" @tap="filter='trial'">限时体验</button></view><view v-if="!shown.length" class="shop-empty"><uni-icons type="shop" size="44" color="#93a1b5"/><text>当前考试暂无在售商品</text><text>考期开启并上架后，即可在这里查看。</text></view><button v-for="p in shown" :key="p.id" class="shop-product" @tap="openPage('/pages/products/index?id='+encodeURIComponent(p.id))"><view class="shop-product-top"><image v-if="p.coverUrl" :src="p.coverUrl" mode="aspectFill"/><view v-else class="shop-symbol"><uni-icons :type="p.type==='trial'?'clock':'medal'" size="30" color="#4168dc"/></view><view><text class="shop-badge">{{p.type==='trial'?'体验权益':'权益套餐'}} · {{p.level.toUpperCase()}}</text><text class="shop-product-title">{{p.title}}</text><text class="shop-period">{{p.year}} 年考期{{p.type==='trial'?' · '+p.trialHours+'小时':''}}</text></view></view><text class="shop-product-intro">{{p.intro||p.examName}}</text><view class="shop-product-bottom"><view class="shop-price">¥<text>{{money(p.priceCents)}}</text><text v-if="p.originalPriceCents" class="shop-original">¥{{money(p.originalPriceCents)}}</text></view><text>查看详情 ›</text></view></button></template>
</view></template>
<style scoped>
