margin-left:4px}.shop-price .shop-original{font-size:12px;color:#77859a;text-decoration:line-through;margin-left:10px;font-weight:400}.detail-cover{width:100%;height:260px;background:#e9edf4}.detail-card{margin:16px;padding:22px;background:#fff;border-radius:14px}.detail-title{display:block;font-size:24px;font-weight:700;line-height:1.5;margin:10px 0}.detail-intro{display:block;font-size:14px;color:#63738a;line-height:1.8;margin-bottom:20px}.detail-card .shop-price{margin-bottom:16px}.shop-section-title{font-size:16px;font-weight:600;display:block;margin-bottom:18px}.purchase-note{display:block;padding:0 22px}.shop-rich{font-size:14px;line-height:1.9;overflow-wrap:anywhere}.shop-rich :deep(img){max-width:100%!important;height:auto!important}.shop-rich :deep(table){max-width:100%;table-layout:fixed}.shop-footer{position:fixed;bottom:0;left:0;right:0;background:#fff;border-top:1px solid #e6ebf2;padding:14px 22px calc(14px + env(safe-area-inset-bottom));display:flex;align-items:center;justify-content:space-between;gap:20px}.shop-footer>view{display:flex;flex-direction:column;gap:5px}.shop-footer>view>text{font-size:12px;color:#63738a}.shop-footer strong{font-size:24px;color:#294bb1}.shop-footer button{margin:0;background:#345ed6;color:#fff;border-radius:24px;padding:0 32px;font-size:15px;line-height:46px}.shop-message,.shop-empty{padding:60px 24px;display:flex;flex-direction:column;align-items:center;text-align:center;gap:16px;color:#63738a;font-size:14px}.shop-empty>text:last-child{font-size:12px}.shop-footer{max-width:430px;margin:auto}
